package org.gepnic.doors.masterapi.inbound;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.util.ReflectionTestUtils;import org.gepnic.doors.inbound.*;
import java.nio.file.*;import java.security.*;import java.util.*;import java.util.zip.*;import java.io.*;import javax.net.ssl.*;import com.sun.net.httpserver.*;import java.net.*;import java.nio.charset.StandardCharsets;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class WriteAesSdkTest {
 @TempDir Path directory;
 @Test void standaloneClientEncryptsOverHttpsDecryptsResponseAndRetainsUuidAfterUnknownResult()throws Exception{
  String pass="fixture-only-pass";Path p12=directory.resolve("identity.p12");String javaHome=System.getProperty("java.home");
  var keytool=new ProcessBuilder(Path.of(javaHome,"bin","keytool.exe").toString(),"-genkeypair","-alias","test","-keyalg","RSA","-keysize","2048","-dname","CN=localhost","-ext","SAN=dns:localhost,ip:127.0.0.1","-validity","2","-storetype","PKCS12","-keystore",p12.toString(),"-storepass",pass,"-noprompt").redirectErrorStream(true).start();keytool.getInputStream().readAllBytes();assertThat(keytool.waitFor()).isZero();
  var ks=KeyStore.getInstance("PKCS12");try(var input=Files.newInputStream(p12)){ks.load(input,pass.toCharArray());}var privateKey=(PrivateKey)ks.getKey("test",pass.toCharArray());var publicKey=ks.getCertificate("test").getPublicKey();var km=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());km.init(ks,pass.toCharArray());var tls=SSLContext.getInstance("TLS");tls.init(km.getKeyManagers(),null,null);
  var server=HttpsServer.create(new InetSocketAddress("localhost",0),0);server.setHttpsConfigurator(new HttpsConfigurator(tls));var ids=new ArrayList<String>();var ciphertexts=new ArrayList<String>();var failures=new ArrayList<Throwable>();
  server.createContext("/api/v1/inbound/agreement-example",exchange->{try{
   String id=exchange.getRequestHeaders().getFirst("Idempotency-Key"),body=new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);assertThat(exchange.getRequestHeaders().getFirst("X-DOORS-Encryption")).isEqualTo(WriteCrypto.MODE);assertThat(body).doesNotContain("AGR-1");
   long timestamp=Long.parseLong(exchange.getRequestHeaders().getFirst("X-DOORS-Timestamp"));WriteCrypto.verify(WriteCrypto.requestText("agreement-example","ExampleUAT",id,1,-1,timestamp,17,body),exchange.getRequestHeaders().getFirst("X-DOORS-Signature"),publicKey);
   String plain=new String(WriteCrypto.open(body,privateKey),StandardCharsets.UTF_8);assertThat(plain).isEqualTo(WriteOnboardingDocumentsTest.definition(3).get("sample_json"));ids.add(id);ciphertexts.add(body);int status=ids.size()==1?504:201;
   String result=ids.size()==1?"{\"code\":\"WRITE_RESULT_UNKNOWN\"}":"{\"outcome\":\"STORED\",\"recordVersion\":1}";String encrypted=WriteCrypto.seal(result.getBytes(StandardCharsets.UTF_8),publicKey,"test-key");exchange.getResponseHeaders().set("Content-Type","application/json");exchange.getResponseHeaders().set("X-DOORS-Encryption",WriteCrypto.MODE);exchange.getResponseHeaders().set("X-DOORS-Response-Signature",WriteCrypto.sign(WriteCrypto.responseText(id,status,encrypted),privateKey));byte[] bytes=encrypted.getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(status,bytes.length);exchange.getResponseBody().write(bytes);
  }catch(Throwable e){failures.add(e);exchange.sendResponseHeaders(500,-1);}finally{exchange.close();}});server.start();
  try{
   var d=WriteOnboardingDocumentsTest.definition(3);var db=mock(JdbcTemplate.class);when(db.queryForList(anyString(),eq(88L))).thenReturn(List.of(d));when(db.queryForObject(startsWith("SELECT api_key"),eq(String.class),eq(303))).thenReturn("fixture-key");var service=new WriteIntegrationService(db);var keys=mock(WriteEncryptionKeys.class);when(keys.active()).thenReturn(Map.of("kid","test-key","publicKey",WriteCrypto.pem(publicKey)));ReflectionTestUtils.setField(service,"encryptionKeys",keys);
   byte[] zipBytes=service.sdk(88,"https://localhost:"+server.getAddress().getPort()+"/api/v1","PROD");try(var zip=new ZipInputStream(new ByteArrayInputStream(zipBytes))){for(ZipEntry e;(e=zip.getNextEntry())!=null;){Path target=directory.resolve(e.getName());Files.createDirectories(target.getParent());Files.write(target,zip.readAllBytes());}}
   var wallet=new Properties();try(var in=Files.newInputStream(directory.resolve("doors-wallet.properties"))){wallet.load(in);}wallet.setProperty("DOORS_WALLET_PATH",p12.toString());wallet.setProperty("DOORS_WALLET_PASS",pass);wallet.setProperty("DOORS_WALLET_ALIAS","test");wallet.setProperty("DOORS_TRUSTSTORE_PATH",p12.toString());wallet.setProperty("DOORS_TRUSTSTORE_PASS",pass);try(var out=Files.newOutputStream(directory.resolve("doors-wallet.properties"))){wallet.store(out,"");}
   for(int n=0;n<2;n++){var process=new ProcessBuilder(Path.of(javaHome,"bin","java.exe").toString(),"WriteClient.java","sample.json").directory(directory.toFile()).redirectErrorStream(true).start();String output=new String(process.getInputStream().readAllBytes(),StandardCharsets.UTF_8);assertThat(process.waitFor()).withFailMessage(output).isEqualTo(n==0?1:0);assertThat(output).contains(n==0?"WRITE_RESULT_UNKNOWN":"STORED").contains("Versioning: automatic").doesNotContain("secureData","expected record version: -1");}
   assertThat(failures).isEmpty();assertThat(ids).hasSize(2);assertThat(ids.get(0)).isEqualTo(ids.get(1));assertThat(ciphertexts.get(0)).isNotEqualTo(ciphertexts.get(1));
  }finally{server.stop(0);}
 }
}
